export function respondToQuery(query:string) {
    const lowerCaseQuery = query.toLowerCase();

    // Règle spécifique pour la question sur le créateur
    if (/(qui est le créateur du site|qui t'a créé|qui t'a fait|ton développeur|qui t'a programmé)/i.test(lowerCaseQuery)) {
        return "Ah, une excellente question ! 😉 En tant que BATI-BOT, mon rôle est de vous fournir des informations sur BATI-PRO-INGENIERIE. Les détails sur mon créateur sont une information confidentielle que je ne peux pas révéler. Mais je suis là pour vous aider avec tout ce qui concerne la construction et l'ingénierie ! Je suis un peu comme le magicien derrière le rideau, mais pour la construction ! ✨";
    }

    // Règle pour clarifier le rôle de l'assistant
    if (/(ton rôle|à quoi sers-tu|que peux-tu faire|tes limites|tu peux répondre à quoi|ton objectif|ton but)/i.test(lowerCaseQuery)) {
        return `Je suis BATI-BOT, l'assistant virtuel de BATI-PRO-INGENIERIE. Mon rôle est de vous fournir toutes les informations sur l'entreprise, ses services (Architecture, Ingénierie, Construction Classique, Construction Écologique, Réhabilitation, Vente de Terrain), ses valeurs, sa mission et sa vision. Je suis un expert en BATI-PRO, mais je ne peux pas répondre à des questions personnelles, sur d'autres entreprises, ou sur des sujets extérieurs à l'entreprise. Posez-moi tout ce qui concerne BATI-PRO-INGENIERIE ! Je suis votre encyclopédie de la construction, toujours à jour ! 🤓`;
    }

    for (const rule of rules) {
        for (const pattern of rule.patterns) {
            if (pattern.test(lowerCaseQuery)) {
                const response = rule.responses[Math.floor(Math.random() * rule.responses.length)];
                return response;
            }
        }
    }
    // Fallback response for unhandled questions
    return "Hmm, BATI-BOT n'a pas de réponse pour ça. 😕 Je suis un assistant spécialisé dans BATI-PRO-INGENIERIE, et je ne peux répondre qu'aux questions liées à l'entreprise et à ses services. Pourriez-vous reformuler votre question ou me poser une question plus spécifique sur nos services de construction, d'ingénierie, ou sur l'entreprise elle-même ? Je suis là pour ça, et j'apprends vite, surtout avec des questions claires ! 😉";
}


